  function onTouchStart(e: React.TouchEvent) { touchY.current = e.touches[0].clientY }
  function onTouchEnd(e: React.TouchEvent) { if (touchY.current === null) return; const dy = touchY.current - e.changedTouches[0].clientY; touchY.current = null; if (Math.abs(dy) < 50) return; if (dy > 0) nextVideo(); else prevVideo() }
  function onWheel(e: React.WheelEvent) { const now = Date.now(); if (now - lastScroll.current < 400) return; lastScroll.current = now; if (e.deltaY > 0) nextVideo(); else prevVideo() }
  function generateAICaption() { setAiLoading(true); setNotice('🤖 AI inatengeneza caption...'); setTimeout(() => { const ideas = [`🔥 ${caption || 'Mombasa Vibes'} Kamata hii! #Vibra #Mombasa #Kamata #FYP #Viral`, `🌴 Mombasa sio mchezo! ${caption || 'Vibra Worldwide'} #Mombasa #Vibra #Trending`, `😂 Hii imenimaliza! ${caption || 'Kamata'} #Comedy #Vibra #Kenya #FYP`, `🎬 Vibra Talent! ${caption || 'Angalia hii'} #VibraTalent #Mombasa #Viral`]; const pick = ideas[Math.floor(Math.random() * ideas.length)]; setCaption(pick); setAiLoading(false); setNotice('🤖 AI Caption Tayari! ✅') }, 1200) }
  function getShareLink() { return window.location.href.split('?')[0] + '?v=' + encodeURIComponent(clipKey) }
  function shareWhatsApp() { window.open('https://wa.me/?text=' + encodeURIComponent('🔥 Angalia hii Vibra! ' + (current?.caption || '') + ' ' + getShareLink()), '_blank'); setShowShare(false); setNotice('WhatsApp imefunguka! ✅') }
