  function shareInstagram() { navigator.clipboard?.writeText(getShareLink()).then(() => setNotice('Link imekopiwa! Fungua Instagram > Post > Paste ✅')); setShowShare(false) }
  function shareCopy() { navigator.clipboard?.writeText(getShareLink() + ' - ' + (current?.caption || '')).then(() => setNotice('Link imekopiwa! 📋')); setShowShare(false) }
  function shareCapCut() { window.open('https://www.capcut.com/', '_blank'); setNotice('CapCut imefunguka! Pakia video uedit ✂️'); setShowShare(false) }
  function startRecording() { if (!streamRef.current) { setNotice('Ruhusu Camera kwanza!'); return }; try { const chunks: any[] = []; const rec = new MediaRecorder(streamRef.current, { mimeType: 'video/webm' }); recorderRef.current = rec; rec.ondataavailable = (e: any) => { if (e.data.size > 0) chunks.push(e.data) }; rec.onstop = () => { const blob = new Blob(chunks, { type: 'video/webm' }); setRecordedBlob(blob); setNotice('✅ Imerekodiwa! Bonyeza Post') }; rec.start(); setIsRecording(true); setNotice('● Inarekodi...') } catch { setNotice('Tumia Upload') } }
  function stopRecording() { if (recorderRef.current) { recorderRef.current.stop(); setIsRecording(false) } }
  async function postRecorded() { if (!recordedBlob) { setNotice('Rekodi kwanza!'); return }; const file = new File([recordedBlob], 'vibra-' + Date.now() + '.webm', { type: 'video/webm' }); await uploadVideo(file) }
  function doSignup() { if (!authName.trim() || !authEmail.trim() || !authPass.trim()) { setAuthError('Jaza Jina, Email na Password'); return }; try { const users = JSON.parse(localStorage.getItem('vibra_users') || '[]'); if (users.find((u: any) => u.email.toLowerCase() === authEmail.toLowerCase())) { setAuthError('Email tayari imeshatumika. Bonyeza Login.'); return }; const nu = { name: authName.trim(), email: authEmail.trim().toLowerCase(), pass: authPass }; users.push(nu); localStorage.setItem('vibra_users', JSON.stringify(users)); localStorage.setItem('vibra_current_user', JSON.stringify(nu)); saveProfileCloud(authEmail.trim().toLowerCase(), authEmail.trim().toLowerCase(), authName.trim()).catch(()=>{}); setAuthUser(nu); setName('@' + authName.trim().replace('@', '')); setShowAuth(false); setNotice('Karibu Vibra! 🎉') } catch { setAuthError('Imeshindwa.') } }
  function doLogin() { if (!authEmail.trim() || !authPass.trim()) { setAuthError('Jaza Email na Password'); return }; try { const users = JSON.parse(localStorage.getItem('vibra_users') || '[]'); const f = users.find((u: any) => u.email.toLowerCase() === authEmail.trim().toLowerCase() && u.pass === authPass); if (!f) { setAuthError('Email au Password si sahihi.'); return }; localStorage.setItem('vibra_current_user', JSON.stringify(f)); setAuthUser(f); setName('@' + f.name.replace('@', '')); setShowAuth(false); setNotice('Karibu tena!') } catch { setAuthError('Imeshindwa.') } }
  function doLogout() { if (!confirm('Toka?')) return; localStorage.removeItem('vibra_current_user'); setAuthUser(null); setShowAuth(true); setView('home'); setShowSettings(false) }
  function toggleSave() { setSavedIds(v => { const n = v.includes(clipKey) ? v.filter(id => id !== clipKey) : [...v, clipKey]; localStorage.setItem('vibra_saved', JSON.stringify(n)); setNotice(n.includes(clipKey) ? 'Ime-save! ✅' : 'Imeondolewa'); return n }) }
  async function toggleFollow() { if (isMine) return; const was = isFollowing; setFollowingIds(v => { const n = v.includes(clipKey) ? v.filter(id => id !== clipKey) : [...v, clipKey]; localStorage.setItem('vibra_following', JSON.stringify(n)); return n }); try { const creator = current?.username || name; await toggleFollowCloud(name, creator, was); await notifyCloud(creator, name, 'follow', clipKey).catch(()=>{}); const c = await getFollowCounts(name); setRealFollowers(c.followers) } catch {} }
  async function addComment() { if (!comment.trim()) return; const t = `${name}: ${comment.trim()}`; const raw = comment.trim(); setComment(''); setLocalComments(prev => { const next = { ...prev, [clipKey]: [...(prev[clipKey] || []), t] }; localStorage.setItem('vibra_local_comments', JSON.stringify(next)); return next }); try { await addCommentCloud(clipKey, name, raw); await notifyCloud(current?.username || name, name, 'comment', clipKey).catch(()=>{}); const m = await getCommentsMap(); setCloudCommentsMap(m) } catch {}; setNotice('Comment imetumwa! ✅') }
  async function uploadVideo(file: File | Blob | undefined) { if (!file || uploading) return; setUploading(true); setNotice('⏳ Inapakia Cloud...'); try { let cp = caption.trim() || selectedHashtags.join(' '); if (!cp.includes('#')) cp += ' ' + selectedHashtags.join(' '); let cloudOk = false; try { await uploadCloudVideo(file as File, name, cp); cloudOk = true } catch (e) { console.log('Cloud fail', e) }; try { const rows = await readCloudVideos(); setCloudClips(rows.map((r: CloudVideo) => ({ id: r.id, url: r.video_url, caption: r.caption || '', username: r.username || '' }))) } catch {}; if (!cloudOk) { const url = URL.createObjectURL(file as Blob); const nc: Clip = { id: Date.now(), url, caption: cp, username: name }; setMyVideos(l => [nc, ...l]) }; setCaption(''); setIdx(0); setView('home'); setPanel(''); setShowCamera(false); setNotice(cloudOk ? 'Video imepakiwa! ✅' : '⚠️ Cloud imeshindwa') } catch { setNotice('Imeshindwa kupakia') } finally { setUploading(false) } }
  function choosePhoto(f: File | undefined) { if (!f) return; const r = new FileReader(); r.onload = () => { const u = String(r.result); setDp(u); localStorage.setItem('vibra_dp', u); setNotice('Picha imehifadhiwa!') }; r.readAsDataURL(f) }
