  function addContact() { if (!newName.trim() || !newPhone.trim()) { setNotice('Jaza Jina na Namba!'); return }; let phone = newPhone.trim(); if (phone.startsWith('0')) phone = '+254' + phone.slice(1); if (!phone.startsWith('+')) phone = '+254' + phone; const id = 'chat_' + name + '_' + newName.trim() + '_' + phone; const avatar = `https://ui-avatars.com/api/?name=${encodeURIComponent(newName.trim())}&background=FE2C55&color=fff&size=150&bold=true`; if (chats.some(c => c.id === id)) { setNotice('Tayari yupo!'); return }; setChats(p => [{ id, name: newName.trim(), avatar, phone, last: 'Sema! Karibu Vibra Chat', time: 'Now', unread: 0, online: true, messages: [] }, ...p]); setSelectedChatId(id); setShowAddContact(false); setNewName(''); setNewPhone(''); setNotice('✅ ' + newName + ' ame-addiwa!') }
  async function openChat(c: any) { setSelectedChatId(c.id); const msgs = await getMessagesCloud(c.id).catch(() => []); setChats(p => p.map(x => x.id === c.id ? { ...x, messages: msgs.map((m: any) => ({ from: m.from_name === name ? 'me' : 'them', text: m.text, time: 'Now' })), unread: 0 } : x)) }
  async function sendChatMsg() { if (!chatInput.trim() || !selectedChat) return; const text = chatInput.trim(); setChatInput(''); const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); setChats(p => p.map(c => c.id === selectedChat.id ? { ...c, last: text, messages: [...c.messages, { from: 'me', text, time }] } : c)); try { await sendMessageCloud(selectedChat.id, name, selectedChat.name, text) } catch {} }
